#include "driver/twai.h"

void setup() {
  auto general = TWAI_GENERAL_CONFIG_DEFAULT(
      GPIO_NUM_5, GPIO_NUM_4, TWAI_MODE_NORMAL);
  auto timing = TWAI_TIMING_CONFIG_500KBITS();
  auto filter = TWAI_FILTER_CONFIG_ACCEPT_ALL();
  ESP_ERROR_CHECK(twai_driver_install(&general, &timing, &filter));
  ESP_ERROR_CHECK(twai_start());
}
